//! libphonenumber-js's `Metadata` and `NumberingPlan` over the bundled `/min`
//! tables (generated by `build.rs` from `metadata.min.json`, version 4). Every
//! accessor keeps the original's fallbacks and truthiness.

use super::js;
use super::PhoneError;

pub struct Format {
    pub pattern: &'static str,
    pub format: &'static str,
    pub leading: &'static [&'static str],
    pub np_rule: Option<&'static str>,
    pub np_optional: bool,
    pub intl: Option<&'static str>,
}

pub struct TypeDef {
    pub pattern: Option<&'static str>,
    pub lengths: Option<&'static [u8]>,
}

pub struct Plan {
    pub calling_code: &'static str,
    pub idd: Option<&'static str>,
    pub national_pattern: Option<&'static str>,
    pub possible_lengths: Option<&'static [u8]>,
    pub formats: Option<&'static [Format]>,
    pub national_prefix: Option<&'static str>,
    pub np_rule: Option<&'static str>,
    pub np_for_parsing: Option<&'static str>,
    pub transform_rule: Option<&'static str>,
    pub np_optional: bool,
    pub leading_digits: Option<&'static str>,
    pub types: Option<&'static [Option<TypeDef>]>,
    pub ext: Option<&'static str>,
}

include!(concat!(env!("OUT_DIR"), "/phone_metadata.rs"));

/// One numbering plan of the bundled metadata.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct PlanId(u16);

impl PlanId {
    pub fn plan(self) -> &'static Plan {
        &PLANS[usize::from(self.0)]
    }
}

/// The names `Object.prototype` carries in every JavaScript engine. A lookup
/// such as `metadata.countries[name]` finds something for these even though
/// the metadata has no such country, and libphonenumber-js acts on it.
pub const PROTOTYPE_KEYS: [&str; 12] = [
    "constructor",
    "__defineGetter__",
    "__defineSetter__",
    "hasOwnProperty",
    "__lookupGetter__",
    "__lookupSetter__",
    "isPrototypeOf",
    "propertyIsEnumerable",
    "toString",
    "valueOf",
    "__proto__",
    "toLocaleString",
];

pub fn is_prototype_key(key: &str) -> bool {
    PROTOTYPE_KEYS.contains(&key)
}

fn lookup(table: &'static [(&'static str, u16)], key: &str) -> Option<PlanId> {
    table
        .binary_search_by(|(k, _)| (*k).cmp(key))
        .ok()
        .map(|i| PlanId(table[i].1))
}

/// `metadata.countries[key]` for an own key.
pub fn country(key: &str) -> Option<PlanId> {
    lookup(COUNTRY_SORTED, key)
}

/// Every country key in the metadata's order (`Object.keys(countries)`).
pub fn country_keys() -> impl Iterator<Item = &'static str> {
    COUNTRY_ORDER.iter().map(|(k, _)| *k)
}

/// `metadata.country_calling_codes[code]` for an own key.
pub fn calling_code_entry(code: &str) -> Option<&'static [&'static str]> {
    CALLING_CODES_SORTED
        .binary_search_by(|(k, _)| (*k).cmp(code))
        .ok()
        .map(|i| CALLING_CODES_SORTED[i].1)
}

/// `getCountryCodesForCallingCode`: the countries of a calling code, none for
/// a non-geographic one (a single three-letter entry, `001`).
pub fn countries_for_code(code: &str) -> Option<&'static [&'static str]> {
    let list = calling_code_entry(code)?;
    if list.len() == 1 && list[0].chars().count() == 3 {
        return None;
    }
    Some(list)
}

fn non_geographic(code: &str) -> Option<PlanId> {
    lookup(NON_GEO_SORTED, code)
}

pub fn has_calling_code(code: &str) -> bool {
    countries_for_code(code).is_some() || non_geographic(code).is_some()
}

/// `getNumberingPlanMetadata(callingCode)`.
pub fn plan_for_code(code: &str) -> Option<PlanId> {
    if let Some(list) = countries_for_code(code) {
        return country(list[0]);
    }
    non_geographic(code)
}

/// `/^\d+$/` (`isCallingCode`).
pub fn is_calling_code(text: &str) -> bool {
    !text.is_empty() && text.bytes().all(|b| b.is_ascii_digit())
}

/// `Metadata#selectNumberingPlan(argument)` for a country or a calling code.
/// Prototype names never reach it: the public entry points refuse them first.
pub fn select(argument: &str) -> Result<Option<PlanId>, PhoneError> {
    if argument.is_empty() {
        return Ok(None);
    }
    if is_calling_code(argument) {
        if !has_calling_code(argument) {
            return Err(PhoneError::error(format!("Unknown calling code: {argument}")));
        }
        return Ok(plan_for_code(argument));
    }
    match country(argument) {
        Some(id) => Ok(Some(id)),
        None => Err(PhoneError::error(format!("Unknown country: {argument}"))),
    }
}

impl Plan {
    fn default_for_code(&self) -> Option<&'static Plan> {
        plan_for_code(self.calling_code).map(PlanId::plan)
    }

    /// The formats, borrowed from the calling code's main country when this
    /// plan has none (`formats()`).
    pub fn formats_list(&self) -> &'static [Format] {
        self.formats
            .or_else(|| self.default_for_code().and_then(|p| p.formats))
            .unwrap_or(&[])
    }

    pub fn np_for_parsing(&self) -> Option<&'static str> {
        self.np_for_parsing.or(self.national_prefix)
    }

    pub fn plan_np_rule(&self) -> Option<&'static str> {
        self.np_rule
            .or_else(|| self.default_for_code().and_then(|p| p.np_rule))
    }

    pub fn plan_np_optional(&self) -> bool {
        self.np_optional || self.default_for_code().is_some_and(|p| p.np_optional)
    }

    fn has_types(&self) -> bool {
        matches!(self.types, Some(list) if !list.is_empty())
    }

    /// `type(name)` by its position in the metadata's type list.
    pub fn type_def(&self, index: usize) -> Option<&'static TypeDef> {
        if !self.has_types() {
            return None;
        }
        self.types?.get(index)?.as_ref()
    }

    pub fn type_lengths(&self, t: &TypeDef) -> Option<&'static [u8]> {
        t.lengths.or(self.possible_lengths)
    }
}

pub const FIXED_LINE: usize = 0;

/// The order `getNumberType` tries the other types in, as metadata positions:
/// MOBILE, PREMIUM_RATE, TOLL_FREE, SHARED_COST, VOIP, PERSONAL_NUMBER, PAGER,
/// UAN, VOICEMAIL.
pub const NON_FIXED_LINE_TYPES: [usize; 9] = [1, 3, 2, 9, 8, 4, 7, 6, 5];

/// A format together with the plan whose `formats()` produced it: its
/// national-prefix rule falls back to that plan's.
#[derive(Clone, Copy)]
pub struct FormatRef {
    pub owner: &'static Plan,
    pub format: &'static Format,
    pub index: usize,
}

impl PartialEq for FormatRef {
    fn eq(&self, other: &Self) -> bool {
        std::ptr::eq(self.format, other.format) && self.index == other.index
    }
}

impl FormatRef {
    pub fn all(owner: &'static Plan) -> Vec<FormatRef> {
        owner
            .formats_list()
            .iter()
            .enumerate()
            .map(|(index, format)| FormatRef { owner, format, index })
            .collect()
    }

    pub fn np_rule(&self) -> Option<&'static str> {
        self.format.np_rule.or_else(|| self.owner.plan_np_rule())
    }

    pub fn np_optional(&self) -> bool {
        self.format.np_optional || self.owner.plan_np_optional()
    }

    pub fn uses_national_prefix(&self) -> bool {
        self.np_rule()
            .is_some_and(|rule| !js::test("^\\(?\\$1\\)?$", rule))
    }

    pub fn np_mandatory(&self) -> bool {
        self.uses_national_prefix() && !self.np_optional()
    }

    pub fn international_format(&self) -> &'static str {
        self.format.intl.unwrap_or(self.format.format)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_hold_the_metadata() {
        assert_eq!(country("ES").map(|p| p.plan().calling_code), Some("34"));
        assert_eq!(calling_code_entry("1").map(|l| l[0]), Some("US"));
        assert_eq!(countries_for_code("800"), None);
        assert!(has_calling_code("800"));
        assert_eq!(plan_for_code("44").map(|p| p.plan().calling_code), Some("44"));
        assert_eq!(country_keys().count(), COUNTRY_ORDER.len());
    }

    #[test]
    fn every_metadata_pattern_compiles() {
        for plan in PLANS {
            for p in [plan.national_pattern, plan.leading_digits, plan.idd, plan.np_for_parsing]
                .into_iter()
                .flatten()
            {
                js::matches_entirely("1", p);
                js::test(&format!("^(?:{p})"), "1");
                js::search(p, "1");
            }
            for t in plan.types.unwrap_or(&[]).iter().flatten() {
                js::matches_entirely("1", t.pattern.unwrap_or(""));
            }
            for f in plan.formats.unwrap_or(&[]) {
                js::matches_entirely("1", f.pattern);
                js::replace_first(f.pattern, "1", f.format);
                for l in f.leading {
                    js::search(l, "1");
                    js::test(&format!("^({l})"), "1");
                }
            }
        }
    }
}
